"""Local sentiment analysis service (DistilBERT SST-2) exposed over Flask."""

import inspect

from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR)
model.eval()


def _build_pipeline():
    """Create a text-classification pipeline, adapting to the installed API."""
    from transformers import pipeline

    params = inspect.signature(pipeline).parameters
    kwargs = {"model": model, "tokenizer": tokenizer}
    # Return every label's score: kwarg name varies across transformers versions.
    if "top_k" in params:
        kwargs["top_k"] = None
    elif "return_all_scores" in params:
        kwargs["return_all_scores"] = True
    try:
        return pipeline("sentiment-analysis", **kwargs)
    except TypeError:
        kwargs.pop("top_k", None)
        kwargs.pop("return_all_scores", None)
        try:
            return pipeline("sentiment-analysis", **kwargs, top_k=None)
        except TypeError:
            return pipeline("sentiment-analysis", **kwargs, return_all_scores=True)


classifier = _build_pipeline()


def _scores(text):
    """Return {'positive': float, 'negative': float} for text."""
    raw = classifier(text, truncation=True)
    # Normalise the several shapes pipelines return across versions.
    while isinstance(raw, list) and raw and isinstance(raw[0], list):
        raw = raw[0]
    if isinstance(raw, dict):
        raw = [raw]

    out = {"positive": 0.0, "negative": 0.0}
    for item in raw:
        label = str(item["label"]).lower()
        score = float(item["score"])
        if "pos" in label or label in ("label_1", "1"):
            out["positive"] = score
        elif "neg" in label or label in ("label_0", "0"):
            out["negative"] = score

    # Single-label result: derive the complement.
    if len(raw) == 1:
        if out["positive"] and not out["negative"]:
            out["negative"] = 1.0 - out["positive"]
        elif out["negative"] and not out["positive"]:
            out["positive"] = 1.0 - out["negative"]
    return out


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True, force=True)
    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": "Missing 'text' field in JSON request body"}), 400

    text = data["text"]
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string"}), 400

    try:
        conf = _scores(text)
    except Exception as exc:  # noqa: BLE001 - report inference failure to caller
        return jsonify({"error": f"Inference failed: {exc}"}), 400

    label = "positive" if conf["positive"] >= conf["negative"] else "negative"
    return jsonify({"sentiment": label, "confidence": conf})


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)

